select 'H-pm', md5(coalesce(string_agg(method||is_active::text||config::text, '|' order by method),'')) from economy_payment_method;
select 'H-pv', md5(coalesce(string_agg(id::text||kind||is_active::text||is_default::text||sandbox::text||config::text, '|' order by id),'')) from publication_provider;
select 'H-lang', md5(coalesce(string_agg(code||name::text||native_name||direction||icon_url||is_active::text||is_default::text||sort::text, '|' order by code),'')) from base_language;
select 'H-cur', md5(coalesce(string_agg(id::text||key||name::text||type||default_value::text||icon_url||metadata::text||sort::text, '|' order by id),'')) from economy_currency;
select 'H-brand', md5(coalesce(string_agg(name::text||short_name||logo_url||logo_dark_url||mark_url||accent||welcome::text, '|'),'')) from base_brand;
select 'H-setup', md5(coalesce(string_agg(status||steps::text||first_opened_by||completed_by||coalesce(completed_at::text,''), '|'),'')) from base_setup;
select 'H-rules', md5(coalesce(string_agg(username_min||'/'||username_max||username_charset||password_min||password_letter::text||password_digit::text||display_name_max, '|'),'')) from base_account_rules;
select 'H-ver', md5(coalesce(string_agg(id::text||platform||latest_version||min_version||store_links::text||update_message::text||force_message::text||is_active::text, '|' order by platform),'')) from base_app_version;
select 'H-ctry', md5(coalesce(string_agg(code||name::text||dial_code||flag_url||is_active::text||sort::text, '|' order by code),'')) from base_country;
select 'H-otp', md5(coalesce(string_agg(is_enabled::text||sandbox::text||coalesce(provider_id::text,'')||code_length||'/'||ttl_seconds||'/'||max_attempts||'/'||resend_seconds||'/'||phone_hourly||'/'||phone_daily||'/'||ip_hourly||message::text, '|'),'')) from publication_otp_settings;
select 'H-words', md5(coalesce(string_agg(id::text||word||action||match||is_active::text||note, '|' order by id),'')) from base_chat_word;
select 'H-rtitles', md5(coalesce(string_agg(id::text||key||name::text||description::text||is_active::text||sort::text, '|' order by id),'')) from base_report_title;
select 'H-evset', md5(coalesce(string_agg(timezone||week_start||'/'||retention_days||'/'||player_rate_limit, '|'),'')) from economy_event_settings;
select 'H-supset', md5(coalesce(string_agg(max_open_tickets||'/'||tickets_per_hour||'/'||messages_per_hour||'/'||max_attachments||'/'||max_attachment_kb||'/'||auto_close_days||chat_enabled::text||chat_greeting::text||chat_offline::text||chat_idle_minutes||'/'||chat_messages_per_minute||'/'||activity_retention_days, '|'),'')) from base_support_settings;
select 'H-dept', md5(coalesce(string_agg(id::text||key||name::text||description::text||first_response_hours||agents::text||is_active::text||sort::text, '|' order by id),'')) from base_support_department;
select 'H-canned', md5(coalesce(string_agg(id::text||key||title::text||body::text||coalesce(department_id::text,'')||is_active::text||sort::text, '|' order by id),'')) from base_support_canned;
select 'H-cfgkey', md5(coalesce(string_agg(id::text||key||type||description||value::text||rules::text||is_active::text||version::text, '|' order by id),'')) from base_config_key;
select 'H-refset', md5(coalesce(string_agg(is_enabled::text||new_account_days||'/'||coalesce(referrer_prize_id::text,'')||coalesce(referee_prize_id::text,'')||coalesce(goal_event_type_id::text,'')||goal_measure||goal_value::text||max_per_referrer||'/'||daily_per_referrer||one_per_device::text||one_per_phone::text||hold_flagged::text, '|'),'')) from economy_referral_settings;
select 'H-updset', md5(coalesce(string_agg(enabled::text||provider||repo||'/'||branch||interval_hours::text||token_sealed, '|'),'')) from base_updates_settings;
